+  const [data, setData] = useState<HotelData | null>(null);
+  const [isPublishing, setIsPublishing] = useState(false);
+  const [publishedUrl, setPublishedUrl] = useState("");
+
+  async function handleRunAgent(event: FormEvent) {
+    event.preventDefault();
+    let parsedUrl: URL;
+    try {
+      parsedUrl = new URL(url);
+      if (!["http:", "https:"].includes(parsedUrl.protocol)) throw new Error();
+    } catch {
+      toast.error("Enter a valid http or https URL.");
+      return;
+    }
+
+    setIsLoading(true);
+    setPublishedUrl("");
+    try {
+      const response = await fetch("/api/agent", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({ url: parsedUrl.toString() }),
+      });
+      const payload = await response.json();
+      if (!response.ok) throw new Error(payload.error || "Agent processing failed.");
+      setData(payload.data as HotelData);
+      toast.success("Hotel data processed.");
+    } catch (error) {
+      setData(null);
+      toast.error(error instanceof Error ? error.message : "Agent processing failed.");
+    } finally {
+      setIsLoading(false);
+    }
+  }
+
+  async function handlePublish() {
+    if (!data) return;
+    setIsPublishing(true);
+    try {
+      const response = await fetch("/api/publish", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({ article: data.blogText, tags: data.tags }),
+      });
+      const payload = await response.json();
+      if (!response.ok) throw new Error(payload.error || "Publication failed.");
+      setPublishedUrl(payload.url);
+      toast.success("Published successfully.");
+    } catch (error) {
+      toast.error(error instanceof Error ? error.message : "Publication failed.");
+    } finally {
+      setIsPublishing(false);
+    }
+  }
+
+  return (
+    <main className="min-h-screen bg-zinc-950 px-4 py-8 text-zinc-100 sm:px-6 lg:px-8">
