 import { NextRequest, NextResponse } from "next/server";
 import type { HotelData } from "@/types";

 function isValidUrl(value: unknown): value is string {
   if (typeof value !== "string") return false;
   try {
     const url = new URL(value);
     return url.protocol === "http:" || url.protocol === "https:";
   } catch {
     return false;
   }
 }

 export async function POST(request: NextRequest) {
   let body: { url?: unknown };
   try {
     body = await request.json();
   } catch {
     return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
   }

   if (!isValidUrl(body.url)) {
     return NextResponse.json({ error: "A valid http or https URL is required." }, { status: 400 });
   }

   const firecrawlKey = process.env.FIRECRAWL_API_KEY;
   const openRouterKey = process.env.OPENROUTER_API_KEY;
   if (!firecrawlKey || !openRouterKey) {
     return NextResponse.json({ error: "Agent API keys are not configured." }, { status: 503 });
   }

   const scrapeResponse = await fetch("https://api.firecrawl.dev/v1/scrape", {
     method: "POST",
     headers: {
       Authorization: `******
       "Content-Type": "application/json",
     },
     body: JSON.stringify({ url: body.url, formats: ["markdown"] }),
   });
   if (!scrapeResponse.ok) {
     return NextResponse.json({ error: "Hotel page could not be scraped." }, { status: 502 });
   }

   const scraped = await scrapeResponse.json();
   const source = typeof scraped.data?.markdown === "string" ? scraped.data.markdown.slice(0, 12000) : "";
   const modelResponse = await fetch("https://openrouter.ai/api/v1/chat/completions", {
     method: "POST",
     headers: {
       Authorization: `******
       "Content-Type": "application/json",
     },
     body: JSON.stringify({
       model: "openai/gpt-4o-mini",
       response_format: { type: "json_object" },
       messages: [
         {
           role: "system",
           content: "Extract hotel details and return valid JSON with hotelName, location, rating, facilities, blogText, imagePrompt, tags. Use only facts from the supplied source.",
         },
         { role: "user", content: source || body.url },
       ],
     }),
   });
   if (!modelResponse.ok) {
     return NextResponse.json({ error: "AI processing failed." }, { status: 502 });
   }

   const modelPayload = await modelResponse.json();
   let generated: Omit<HotelData, "imageUrl">;
   try {
     generated = JSON.parse(modelPayload.choices[0]?.message?.content || "{}");
   } catch {
     return NextResponse.json({ error: "AI returned invalid data." }, { status: 502 });
   }

   const imagePrompt = String(generated.imagePrompt || `${generated.hotelName} hotel exterior`);
   const imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(imagePrompt)}?width=1200&height=750&nologo=true`;
   const data: HotelData = {
     hotelName: String(generated.hotelName || ""),
     location: String(generated.location || ""),
     rating: String(generated.rating || ""),
     facilities: Array.isArray(generated.facilities) ? generated.facilities.map(String) : [],
     blogText: String(generated.blogText || ""),
     imagePrompt,
     imageUrl,
     tags: Array.isArray(generated.tags) ? generated.tags.map(String).slice(0, 4) : [],
   };

   return NextResponse.json({ data });
 }

