 import { NextRequest, NextResponse } from "next/server";

 export async function POST(request: NextRequest) {
   let body: { article?: unknown; tags?: unknown };
   try {
     body = await request.json();
   } catch {
     return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
   }

   if (typeof body.article !== "string" || body.article.trim().length < 20) {
     return NextResponse.json({ error: "Article text must contain at least 20 characters." }, { status: 400 });
   }
   const tags = Array.isArray(body.tags)
     ? body.tags.filter((tag): tag is string => typeof tag === "string").slice(0, 4)
     : [];
   const apiKey = process.env.DEVTO_API_KEY;
   if (!apiKey) {
     return NextResponse.json({ error: "DEVTO_API_KEY is not configured." }, { status: 503 });
   }

   const response = await fetch("https://dev.to/api/articles", {
     method: "POST",
     headers: {
       "api-key": apiKey,
       "Content-Type": "application/json",
     },
     body: JSON.stringify({
       article: {
         title: "Hotel Review and Travel Guide",
         body_markdown: body.article,
         published: true,
         tags,
       },
     }),
   });
   const payload = await response.json();
   if (!response.ok) {
     return NextResponse.json({ error: "Dev.to rejected the article." }, { status: 502 });
   }

   return NextResponse.json({ url: payload.url });
 }

