 "use client";

 import Image from "next/image";
 import { FormEvent, useState } from "react";
 import { motion } from "framer-motion";
 import { Link2, LoaderCircle, MapPin, Sparkles, Star } from "lucide-react";
 import { toast } from "sonner";
 import { Badge } from "@/components/ui/badge";
 import { Button } from "@/components/ui/button";
 import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
 import { Input } from "@/components/ui/input";
 import { Skeleton } from "@/components/ui/skeleton";
 import type { HotelData } from "@/types";

 export default function Home() {
   const [url, setUrl] = useState("");
   const [isLoading, setIsLoading] = useState(false);
   const [data, setData] = useState<HotelData | null>(null);
   const [isPublishing, setIsPublishing] = useState(false);
   const [publishedUrl, setPublishedUrl] = useState("");

   async function handleRunAgent(event: FormEvent) {
     event.preventDefault();
     let parsedUrl: URL;
     try {
       parsedUrl = new URL(url);
       if (!["http:", "https:"].includes(parsedUrl.protocol)) throw new Error();
     } catch {
       toast.error("Enter a valid http or https URL.");
       return;
     }

     setIsLoading(true);
     setPublishedUrl("");
     try {
       const response = await fetch("/api/agent", {
         method: "POST",
         headers: { "Content-Type": "application/json" },
         body: JSON.stringify({ url: parsedUrl.toString() }),
       });
       const payload = await response.json();
       if (!response.ok) throw new Error(payload.error || "Agent processing failed.");
       setData(payload.data as HotelData);
       toast.success("Hotel data processed.");
     } catch (error) {
       setData(null);
       toast.error(error instanceof Error ? error.message : "Agent processing failed.");
     } finally {
       setIsLoading(false);
     }
   }

   async function handlePublish() {
     if (!data) return;
     setIsPublishing(true);
     try {
       const response = await fetch("/api/publish", {
         method: "POST",
         headers: { "Content-Type": "application/json" },
         body: JSON.stringify({ article: data.blogText, tags: data.tags }),
       });
       const payload = await response.json();
       if (!response.ok) throw new Error(payload.error || "Publication failed.");
       setPublishedUrl(payload.url);
       toast.success("Published successfully.");
     } catch (error) {
       toast.error(error instanceof Error ? error.message : "Publication failed.");
     } finally {
       setIsPublishing(false);
     }
   }

   return (
     <main className="min-h-screen bg-zinc-950 px-4 py-8 text-zinc-100 sm:px-6 lg:px-8">
       <div className="mx-auto max-w-7xl">
         <header className="mb-6 flex items-center gap-3 border-b border-zinc-800 pb-5">
           <Sparkles className="size-6 text-emerald-400" aria-hidden="true" />
           <h1 className="text-xl font-semibold tracking-tight sm:text-2xl">Hotel AI Auto-Publisher</h1>
         </header>

         <form onSubmit={handleRunAgent} className="mb-6 flex flex-col gap-3 sm:flex-row">
           <label htmlFor="hotel-url" className="sr-only">Hotel URL</label>
           <div className="relative flex-1">
             <Link2 className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-zinc-400" aria-hidden="true" />
             <Input
               id="hotel-url"
               type="url"
               value={url}
               onChange={(event) => setUrl(event.target.value)}
               placeholder="https://hotel.example.com"
               className="h-11 pl-10"
               disabled={isLoading}
             />
           </div>
           <Button type="submit" className="h-11 min-w-36" disabled={isLoading}>
             {isLoading && <LoaderCircle className="mr-2 size-4 animate-spin" aria-hidden="true" />}
             {isLoading ? "Processing..." : "Run Agent"}
           </Button>
         </form>

         <section className="grid grid-cols-1 gap-4 lg:grid-cols-3" aria-live="polite">
           {isLoading ? (
             [0, 1, 2].map((column) => (
               <Card key={column} className="min-h-[360px] bg-zinc-900">
                 <CardHeader><Skeleton className="h-5 w-32" /></CardHeader>
                 <CardContent className="space-y-3">
                   <Skeleton className="h-40 w-full" />
                   <Skeleton className="h-4 w-4/5" />
                   <Skeleton className="h-4 w-3/5" />
                 </CardContent>
               </Card>
             ))
           ) : data ? (
             <>
               <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25 }}>
                 <Card className="h-full min-h-[360px] bg-zinc-900">
                   <CardHeader><CardTitle>Hotel Data</CardTitle></CardHeader>
                   <CardContent className="space-y-5">
