 import { lookup } from "node:dns/promises";
 import type { HotelData } from "@/types";

 export function isValidPublicUrl(value: unknown): value is string {
   if (typeof value !== "string" || value.length > 2048) return false;
   try {
     const url = new URL(value);
     return (
       (url.protocol === "http:" || url.protocol === "https:") &&
       Boolean(url.hostname) &&
       !url.username &&
       !url.password
     );
   } catch {
     return false;
   }
 }

 function isPrivateAddress(address: string): boolean {
   if (address.includes(":")) {
     const normalized = address.toLowerCase();
     return normalized === "::1" || normalized === "::" ||
       normalized.startsWith("fc") || normalized.startsWith("fd") ||
       normalized.startsWith("fe8") || normalized.startsWith("fe9") ||
       normalized.startsWith("fea") || normalized.startsWith("feb") ||
       normalized.startsWith("::ffff:127.") || normalized.startsWith("::ffff:10.") ||
       normalized.startsWith("::ffff:192.168.") || normalized.startsWith("::ffff:172.");
   }
   const parts = address.split(".").map(Number);
   if (parts.length !== 4 || parts.some((part) => !Number.isInteger(part))) return true;
   const [a, b] = parts;
   return (
     a === 0 || a === 10 || a === 127 || (a === 169 && b === 254) ||
     (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) ||
     a >= 224
   );
 }

 export async function validatePublicUrl(value: string): Promise<void> {
   if (!isValidPublicUrl(value)) throw new Error("A valid http or https URL is required.");
   const url = new URL(value);
   const hostname = url.hostname.toLowerCase();
   if (
     hostname === "localhost" ||
     hostname.endsWith(".localhost") ||
     hostname.endsWith(".local") ||
     hostname === "169.254.169.254"
   ) {
     throw new Error("Internal network URLs are not allowed.");
   }
   const addresses = await lookup(hostname, { all: true });
   if (addresses.length === 0 || addresses.some(({ address }) => isPrivateAddress(address))) {
     throw new Error("Internal network URLs are not allowed.");
   }
 }

 export async function processHotelUrl(url: string): Promise<HotelData> {
   await validatePublicUrl(url);
   const firecrawlKey = process.env.FIRECRAWL_API_KEY;
   const openRouterKey = process.env.OPENROUTER_API_KEY;
   if (!firecrawlKey || !openRouterKey) {
     throw new Error("Agent API keys are not configured.");
   }

   const scrapeResponse = await fetch("https://api.firecrawl.dev/v1/scrape", {
     method: "POST",
     headers: {
       Authorization: `******
       "Content-Type": "application/json",
     },
     body: JSON.stringify({ url, formats: ["markdown"], proxy: "stealth" }),
   });
   if (!scrapeResponse.ok) throw new Error("Hotel page could not be scraped.");

   const scraped = await scrapeResponse.json();
   const source =
     typeof scraped.data?.markdown === "string"
       ? scraped.data.markdown.slice(0, 12000)
       : "";

   const schema = {
     type: "object",
     additionalProperties: false,
     properties: {
       title: { type: "string" },
       hotelName: { type: "string" },
       location: { type: "string" },
       rating: { type: "string" },
       facilities: { type: "array", items: { type: "string" }, maxItems: 12 },
       blogText: { type: "string" },
       imagePrompt: { type: "string" },
       tags: { type: "array", items: { type: "string" }, maxItems: 4 },
     },
     required: ["title", "hotelName", "location", "rating", "facilities", "blogText", "imagePrompt", "tags"],
   };

   const modelResponse = await fetch("https://openrouter.ai/api/v1/chat/completions", {
     method: "POST",
     headers: {
       Authorization: `******
       "Content-Type": "application/json",
     },
     body: JSON.stringify({
       model: "openrouter/free",
       response_format: {
         type: "json_schema",
         json_schema: { name: "hotel_article", strict: true, schema },
       },
       messages: [
         {
           role: "system",
           content: "Create structured hotel content using only facts from the supplied source. Return title, hotelName, location, rating, facilities, blogText, imagePrompt, and tags. Do not add unsupported details.",
         },
         { role: "user", content: source || url },
       ],
     }),
   });
   if (!modelResponse.ok) throw new Error("AI processing failed.");

   const modelPayload = await modelResponse.json();
   let generated: {
     title?: string;
     hotelName?: string;
     location?: string;
     rating?: string;
     facilities?: string[];
     blogText?: string;
     imagePrompt?: string;
     tags?: string[];
   };
   try {
     generated = JSON.parse(modelPayload.choices?.[0]?.message?.content || "{}");
   } catch {
     throw new Error("AI returned invalid data.");
   }

   const title = String(generated.title || "Hotel Guide");
   const blogText = String(generated.blogText || "");
   const imagePrompt = String(generated.imagePrompt || `${title} hotel exterior`);
   const imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(imagePrompt)}?width=1200&height=750&nologo=true`;
   const tags = Array.isArray(generated.tags)
     ? generated.tags.map((tag) => String(tag).trim()).filter(Boolean).slice(0, 4)
     : [];

   return {
     title,
     hotelName: String(generated.hotelName || title),
     location: String(generated.location || ""),
     rating: String(generated.rating || ""),
     facilities: Array.isArray(generated.facilities)
       ? generated.facilities.map((facility) => String(facility).trim()).filter(Boolean).slice(0, 12)
       : [],
     blogText,
     imagePrompt,
     imageUrl,
     tags,
   };
 }

